window.bookSummaryJSON = "<p><b>The craving was maddening. Uncontrollable.</b></p> <p>I inhaled her. My fangs ached. And every time I looked into her eyes, the dagger of desire was thrust ever further into my broken soul.</p> <p>I—the Quiet King—who held dominion over countless beings, found myself absolutely enslaved by this enchanting blood mage.</p> <p>But would she ever submit to me?</p> <p>Or would I have to take what I desire?</p>"; 
